"""Self-contained HTML conformance report for one persisted VidyutSetu run.

No template engine and no new dependency: the page is built from the run that was
actually stored, with every interpolated value HTML-escaped.
"""

from __future__ import annotations

from datetime import datetime, timezone
from html import escape
from typing import Any, Mapping, Sequence

DISCLOSURE = (
    "This report was generated by VidyutSetu from a single test run. The fault "
    "classifier and anomaly screen are trained on synthetic AMI data, need reading "
    "history to be meaningful, and are screening aids only. Rule-based standard "
    "checks remain authoritative. This report does not certify compliance with "
    "IEC 61968-9, DLSS/COSEM or IS 15959."
).replace("DLSS", "DLMS")


def _row(label: str, value: Any) -> str:
    return f"<tr><th>{escape(str(label))}</th><td>{escape(str(value))}</td></tr>"


def _issues_table(issues: Sequence[Mapping[str, Any]]) -> str:
    if not issues:
        return "<p class=\"empty\">No rule diagnostics were recorded for this run.</p>"
    rows = []
    for issue in issues:
        rows.append(
            "<tr>"
            f"<td class=\"sev\">{escape(str(issue.get('severity', '')))}</td>"
            f"<td><code>{escape(str(issue.get('code', '')))}</code></td>"
            f"<td>{escape(str(issue.get('field') or '-'))}</td>"
            f"<td>{escape(str(issue.get('message', '')))}</td>"
            f"<td>{escape(str(issue.get('suggested_fix') or '-'))}</td>"
            "</tr>"
        )
    return (
        "<table class=\"issues\"><thead><tr><th>Severity</th><th>Code</th>"
        "<th>Field</th><th>Finding</th><th>Suggested action</th></tr></thead>"
        "<tbody>" + "".join(rows) + "</tbody></table>"
    )


def build_run_report(
    run: Any,
    issues: Sequence[Mapping[str, Any]],
    generated_at: datetime | None = None,
) -> str:
    """Render the conformance report for a ``DBTestRun`` row."""
    generated = (generated_at or datetime.now(timezone.utc)).isoformat()
    data_quality = (
        f"{run.data_quality_score:.1f} / 100"
        if run.data_quality_score is not None
        else "not recorded for this run"
    )
    model_version = run.model_version or "not recorded for this run"

    summary_rows = "".join(
        [
            _row("Run id", run.run_id),
            _row("Executed at", run.execution_time.isoformat() if run.execution_time else "-"),
            _row("Source vendor", run.source_vendor),
            _row("Target vendor", run.target_vendor or "none"),
            _row("Total records", run.total_records),
            _row("Valid records", run.valid_records),
            _row("Invalid records", run.invalid_records),
            _row("Model version tag", model_version),
            _row("Data-quality score", data_quality),
            _row("Run duration (ms)", run.duration_ms),
        ]
    )
    pillar_rows = "".join(
        [
            _row("Syntactic conformance", run.syntactic_score),
            _row("Semantic conformance", run.semantic_score),
            _row("Data integrity & physical sanity", run.integrity_score),
            _row("Weighted total score", run.total_score),
            _row("Grade", run.grade),
        ]
    )

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>VidyutSetu conformance report {escape(run.run_id)}</title>
<style>
  :root {{ --navy:#0B2545; --teal:#0E9AA7; --amber:#F59E0B; --bg:#F4F8FB; }}
  body {{ margin:0; padding:32px; font-family:Segoe UI, Roboto, Helvetica, Arial, sans-serif;
         color:#13263b; background:var(--bg); }}
  header {{ border-bottom:3px solid var(--navy); padding-bottom:12px; margin-bottom:24px; }}
  h1 {{ margin:0 0 4px; font-size:22px; color:var(--navy); }}
  h2 {{ font-size:15px; color:var(--navy); margin:28px 0 8px; text-transform:uppercase;
        letter-spacing:.06em; }}
  .score {{ font-size:34px; font-weight:700; color:var(--navy); }}
  .grade {{ color:var(--teal); font-weight:600; }}
  table {{ border-collapse:collapse; width:100%; background:#fff; font-size:13px; }}
  th, td {{ border:1px solid #d6e3ee; padding:7px 9px; text-align:left; vertical-align:top; }}
  th {{ background:#eaf2f8; font-weight:600; }}
  table th:first-child {{ width:32%; }}
  .sev {{ font-weight:600; color:var(--amber); white-space:nowrap; }}
  pre {{ background:#0B2545; color:#e8f1f8; padding:12px; overflow:auto; font-size:12px; }}
  .disclosure {{ margin-top:24px; padding:14px 16px; border-left:4px solid var(--amber);
                 background:#fff7e6; font-size:12px; line-height:1.55; }}
  .meta {{ color:#5b7288; font-size:12px; }}
</style>
</head>
<body>
<header>
  <h1>VidyutSetu — AMI Interoperability Conformance Report</h1>
  <p class="meta">Run {escape(run.run_id)} · generated {escape(generated)} ·
     IEC 61968-9 aligned workbench output</p>
</header>

<p class="score">{escape(str(run.total_score))} <span class="grade">({escape(str(run.grade))})</span></p>
<p class="meta">{escape(run.summary or "")}</p>

<h2>Run summary</h2>
<table>{summary_rows}</table>

<h2>Score breakdown</h2>
<table>{pillar_rows}</table>

<h2>Rule diagnostics</h2>
{_issues_table(issues)}

<h2>Submitted payload preview</h2>
<pre>{escape((run.raw_preview or "")[:4000])}</pre>

<div class="disclosure">{escape(DISCLOSURE)}</div>
</body>
</html>
"""
